    for r in csv.DictReader(f):
        a,b=r['from_id'],r['to_id']; m=float(r['minutes'])
        boat[a][b]=m; boat[b][a]=m
# optional drones per node
opt_dr=collections.defaultdict(list)
with open(base/'drone_options.csv') as f:
    for r in csv.DictReader(f):
        if r['payload_feasible']=='1' and sp[r['launch_node']]['launch_clearance']"'!='"'poor' and float(r['flight_minutes'])<=cfg['drone_endurance_minutes']:
            opt_dr[r['launch_node']].append(r['shelter_id'])
# mandatory directs per node
mand=collections.defaultdict(list)
for s in shel.values():
    if s['area_type']=='dry': mand[s['nearest_dry_node']].append(s['shelter_id'])
ramps=[n for n,r in sp.items() if r['boat_ramp']=='1']
# boat trips
mult=1.12
trip_count={}
for ramp in ramps:
    c=[]
    def dfs(path, load, travel):
        last=path[-1] if path else ramp
        if path and ramp in boat[last]:
            dur=cfg['boat_setup_minutes'] + mult*(travel + boat[last][ramp]) + cfg['boat_unload_minutes_per_shelter']*len(path)
            if load<=cfg['boat_capacity_kg'] and dur<=cfg['boat_trip_limit_minutes']+1e-9:
                c.append(tuple(path))
        for nxt,m in boat[last].items():
            if not nxt.startswith('H') or nxt in path: continue
            nload=load+float(shel[nxt]['demand_kg'])
            if nload>cfg['boat_capacity_kg']+1e-9 or ramp not in boat[nxt]: continue
            ndur=cfg['boat_setup_minutes'] + mult*(travel+m+boat[nxt][ramp]) + cfg['boat_unload_minutes_per_shelter']*(len(path)+1)
            if ndur>cfg['boat_trip_limit_minutes']+1e-9: continue
            dfs(path+[nxt], nload, travel+m)
    dfs([],0.0,0.0)
    trip_count[ramp]=len(c)
for node in sorted(set(mand)|set(opt_dr)|set(ramps)):
    m=mand.get(node,[])
    d=opt_dr.get(node,[])
    b=trip_count.get(node,0)
    total=0
    for k in range(len(d)+1):
        for subset in itertools.combinations(d,k):
            total += math.factorial(len(m)+k)
            if b:
                total += b*math.factorial(len(m)+k+1)
    print(node,'mandatory',len(m),'drones',len(d),'boattrips',b,'patterns~',total)
