import importlib.util
spec = importlib.util.spec_from_file_location('solver', '/app/submissions/solve.py')
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)
inst = mod.load_instance()
travel_time, travel_path = mod.build_shortest_paths(inst)
trips = mod.generate_boat_trips(inst)
patterns_by_node, lookup = mod.build_patterns(inst, trips)
flooded = inst['flooded']
idx = {h:i for i,h in enumerate(flooded)}
mandatory = set(inst['dry_by_node'])
states = {0:[(0.0,{})]}
for node in inst['relevant_nodes']:
    new = {}
    options = list(patterns_by_node[node])
    if node not in mandatory:
        options = [None] + options
    for mask, arr in states.items():
        for cost, chosen in arr:
            for pat in options:
                if pat is None:
                    nmask=mask; ncost=cost; nchosen=chosen
                else:
                    pmask=0
                    for h in pat['flooded_covered']:
                        pmask |= 1<<idx[h]
                    if mask & pmask:
                        continue
                    nmask=mask|pmask
                    base=min(d['duration'] for d in pat['period_data'].values())
                    ncost=cost+base+(0 if node in mandatory else 18)
                    nchosen=dict(chosen); nchosen[node]=pat
                new.setdefault(nmask,[]).append((ncost,nchosen))
    states={}
    for mask, arr in new.items():
        arr.sort(key=lambda x:x[0])
        kept=[]; seen=set()
        for cost, chosen in arr:
            key=tuple(sorted((n,p['pattern_id']) for n,p in chosen.items()))
            if key in seen: continue
            seen.add(key); kept.append((cost,chosen))
            if len(kept)>=5: break
        states[mask]=kept
    print('after', node, 'states', len(states))
full=(1<<len(flooded))-1
cands=states[full]
print('candidate covers', len(cands))
best=None
for k,(approx, chosen) in enumerate(cands[:5], start=1):
    order, eva = mod.best_route_for_patterns(inst, travel_time, chosen)
    print(k, 'approx', round(approx,3), 'obj', round(eva['objective'],3), 'nodes', len(chosen), 'order', order)
    if best is None or eva['objective']<best[0]:
        best=(eva['objective'], chosen, order, eva)
print('BEST', best[0], best[2])
for n in sorted(best[1]):
    p=best[1][n]
    print(n, p['pattern_id'], p['kind'], p['flooded_covered'])
